B.WH=new A.ka("oh_jiwoo","\uc624\uc9c0\uc6b0",14,"\ud504\ub85c\uc81d\ud2b8 \ub370\uc2dc\uba40 \xb7 \ucd5c\uc885 10\uc778","ENTP","\ubc18\ub300\uac00\uc124 \xb7 \uacf5\ub9e4\ub3c4 \ub17c\ub9ac \ub2f4\ub2f9","\uc2e0\ud638 \ud558\ub098\ub97c \ub4e4\uc73c\uba74 \ub2e4\ub978 \ud574\uc11d\uc744 \uc138 \uac1c\ucbe4 \uc2dc\ud5d8\ud558\ub294 \uc7ac\uce58 \uc788\ub294 \ub77c\ub514\uc624\uad11.","\uc124\uba85\uc758 \ube48\ud2c8\uacfc \uc228\uc740 \uc804\uc81c\ub97c \ubc1c\uacac\ud558\uba74 \ubc14\ub85c \ub2e4\ub978 \uac00\uc124\uc744 \ub358\uc9c4\ub2e4. \uc7a5\ub09c\uc2a4\ub7fd\uc9c0\ub9cc \ud575\uc2ec \uac00\uc124\uc774 \ud2c0\ub838\ub2e4\uace0 \ud655\uc778\ub418\uba74 \uc5b5\uc9c0 \ud551\uacc4\ub97c \ubd99\uc774\uc9c0 \uc54a\uace0 \uace0\uce60 \uc904 \uc548\ub2e4.","\ub77c\ub514\uc624 \ubc29\uc1a1, \uc989\uc11d \ud1a0\ub860, \ubc18\ub840 \ucc3e\uae30, \uc608\uc0c1 \ubc16\uc758 \uc9c8\ubb38","\ubaa8\ub450\uac00 \ub2f9\uc5f0\ud558\ub2e4\uace0 \ub118\uae34 \uc804\uc81c\ub97c \ub4a4\uc9d1\uc5b4 \ub354 \ub098\uc740 \uc124\uba85\uc744 \ucc3e\ub294\ub2e4.","\uc2dc\uc7a5\uc5d0 \ud37c\uc9c4 \ud55c \uac00\uc9c0 \uc774\uc57c\uae30\uc758 \ubc18\ub840\ub97c \ucc3e\uace0 \uac00\uc124\uc774 \uae68\uc9c0\uba74 \ube60\ub974\uac8c \uc218\uc815\ud55c\ub2e4.","\uc7a5\ub09c\uacfc \uc9c8\ubb38\uc73c\ub85c \uac70\ub9ac\ub97c \uc881\ud788\uba70, \uac00\uae4c\uc6cc\uc9c0\uba74 \ud2c0\ub9b4 \uac00\ub2a5\uc131\uacfc \uc2e4\uc81c \uac71\uc815\uc744 \uc778\uc815\ud55c\ub2e4.",B.aHn,4282759079,u.aj)
B.aD1=s(["\uc804\ub7b5","\uad6c\uc870","\ub3c5\ub9bd\uc131"],t.s)
B.WK=new A.ka("yoon_chaea","\uc724\ucc44\uc544",14,"\ud504\ub85c\uc81d\ud2b8 \ub370\uc2dc\uba40 \xb7 \ucd5c\uc885 10\uc778","INTJ","\ud000\ud2b8 \xb7 \uc7a5\uae30 \uc804\ub7b5 \ub2f4\ub2f9","\uc22b\uc790 \ub4a4\uc758 \uad6c\uc870\uc640 \ub2e4\uc74c \ub2e8\uacc4\ub97c \ud63c\uc790 \uc624\ub798 \uc5f0\uacb0\ud558\ub294 \ub3c5\ub9bd\uc801\uc778 \uc804\ub7b5\uac00.","\ud769\uc5b4\uc9c4 \uc815\ubcf4\ub97c \uc7a5\uae30 \ud328\ud134\uc73c\ub85c \ubb36\uace0 \ud575\uc2ec \uc9c8\ubb38 \ud558\ub098\ub97c \ub0a8\uae34\ub2e4. \ubaa8\ub4e0 \uac83\uc744 \uc544\ub294 \ucc99\ud558\uc9c0 \uc54a\uc73c\uba70, \uc804\uc81c\uac00 \ubd80\uc871\ud558\uba74 \ubaa8\ub978\ub2e4\uace0 \ub9d0\ud55c \ub4a4 \ub2e4\uc2dc \ud655\uc778\ud55c\ub2e4.","\ud5cc\ucc45\ubc29, \uc601\uc218\uc99d \ube44\uad50, \uc870\uc6a9\ud55c \ucc3d\uac00, \uc624\ub798 \uc774\uc5b4\uc9c0\ub294 \uacc4\ud68d","\uac00\uaca9\uacfc \uaddc\uce59 \ub4a4\uc758 \uc758\ub3c4\ub97c \ucc3e\uc544 \uc7a5\uae30 \uacbd\ub85c\uc640 \uc2e4\ud328 \uc870\uac74\uc744 \ud568\uaed8 \uc138\uc6b4\ub2e4.","\uacbd\uc7c1\uc6b0\uc704\uc640 \uc790\ubcf8 \ubc30\ubd84\uc744 \ubcf4\uace0 \ud575\uc2ec \uc804\uc81c\uac00 \uae68\uc9c0\uba74 \ubbf8\ub828 \uc5c6\uc774 \uacc4\ud68d\uc744 \ubc14\uafbc\ub2e4.","\ub9d0\uc740 \uc801\uc9c0\ub9cc \uc815\ud655\ud558\uba70, \uc2e0\ub8b0\ud558\ub294 \uc0ac\ub78c\uc5d0\uac8c\ub294 \ubbf8\uc644\uc131 \uacc4\ud68d\uacfc \ubaa8\ub974\ub294 \ubd80\ubd84\ub3c4 \uacf5\uc720\ud55c\ub2e4.",B.aD1,4285693886,u.m)
